        0 56px, /* 图层3: 分割线 (头像下方) */
        16px calc(100% - 54px), /* 图层4: 操作栏 (距底54px) */
        calc(100% - 16px) calc(100% - 54px), /* 图层5: 收藏 (距底54px，靠右) */
        16px calc(100% - 8px) !important; /* 图层6: 文字 (最底部) */

    background-repeat: no-repeat !important;
}

/* ── 5. 强制头像变成正圆 (Ins风格) ── */
