.msg-sim-card::after { content: "" !important; position: absolute !important; top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important; background-image: url('https://s3.bmp.ovh/2026/08/10/GGXzrt3R.jpg') !important; background-size: cover !important; background-position: center !important; background-repeat: no-repeat !important; z-index: 10 !important; opacity: 1 !important; transition: opacity 0.25s ease !important; }
