  --reply-detached-border-left: none; --reply-detached-border: none;
  --reply-detached-name-color: #858585; --reply-detached-name-suffix: "："; --reply-detached-name-size: 12px; --reply-detached-name-weight: 500;
  --reply-detached-text-color: #888888; --reply-detached-text-size: 12px; --reply-detached-text-whitespace: nowrap;
  --reply-detached-media-color: #888888;
}

/* =========================================================
   🎭 文字图伪装魔法 (长按揭秘 + 自由调大小 + 纯尖角) 🎭
   ========================================================= */
:root {
  --sim-card-max-width: 180px; --sim-card-min-height: 120px; --sim-card-font-size: 13px; --sim-card-padding: 12px;
}
.msg-sim-card { position: relative !important; overflow: hidden !important; border-radius: 0 !important; border: none !important; cursor: pointer !important; max-width: var(--sim-card-max-width) !important; min-height: var(--sim-card-min-height) !important; padding: var(--sim-card-padding) !important; font-size: var(--sim-card-font-size) !important; line-height: 1.5 !important; }
.msg-sim-card::after { content: "" !important; position: absolute !important; top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important; background-image: url('https://s3.bmp.ovh/2026/08/10/GGXzrt3R.jpg') !important; background-size: cover !important; background-position: center !important; background-repeat: no-repeat !important; z-index: 10 !important; opacity: 1 !important; transition: opacity 0.25s ease !important; }
.msg-sim-card:active::after, .msg-sim-card:hover::after { opacity: 0 !important; pointer-events: none !important; }

/* 对方图片：去掉气泡 【不用改，样式容器隐藏用】 */
.msg-them:has(.msg-image-wrapper) .msg-bubble-container,
.msg-them:has(.msg-image-wrapper) .bubble-them-custom {
   background: transparent !important;
   border: none !important;
   box-shadow: none !important;
   padding: 0 !important;
}

/* ==========【修改图片最大尺寸、圆角 在这里！】========== */
/* 对方图片外层容器 */
.msg-them .msg-image-wrapper {
   /* 图片圆角值，改这里数字，8=8px圆角 */
   border-radius: 8px !important;
   overflow: hidden !important;
   border: none !important;
   box-shadow: none !important;
   background: transparent !important;
   position: relative !important;
   top: 0px !important;
   left: 0px !important;
   /* 图片最大宽度（横向上限） */
   max-width: 130px !important;
   /* 图片最大高度（纵向上限） */
   max-height: 173px !important;
   width: auto !important;
   height: auto !important;
}
/* 对方内部图片 圆角同步，改上面数字这里同步改即可 */
.msg-them .msg-image-wrapper img {
   width: 100% !important;
   height: auto !important;
   object-fit: cover !important;
   border-radius: 8px !important;
}

/* 我方图片外层容器 和上面对方参数完全一致，改这里同步尺寸圆角 */
.msg-me .msg-image-wrapper {
   /* 图片圆角 */
   border-radius: 8px !important;
   overflow: hidden !important;
   border: none !important;
   box-shadow: none !important;
   background: transparent !important;
   position: relative !important;
   top: 0px !important;
   left: 0px !important;
   /* 图片最大宽 */
   max-width: 130px !important;
   /* 图片最大高 */
   max-height: 173px !important;
   width: auto !important;
   height: auto !important;
}
/* 我方内部图片圆角 */
.msg-me .msg-image-wrapper img {
   width: 100% !important;
   height: auto !important;
   object-fit: cover !important;
   border-radius: 8px !important;
}
/* ===================================================== */

/* 去除表情包气泡 【不用改】 */
div[class*="message"] div[class*="bubble"]:has(img):not(:has([class*="avatar"])):not(:has(.msg-image-wrapper)):not(:has([class*="reply"])) {
   background: transparent !important;
   border: none !important;
   box-shadow: none !important;
   padding: 0 !important;
   border-radius: 0 !important;
   outline: none !important;
}

/* ==========【修改表情包大小 在这里！】========== */
div[class*="message"] div[class*="bubble"]:not(:has([class*="avatar"])):not(:has(.msg-image-wrapper)):not(:has([class*="reply"])) img {
   /* 表情包宽度 */
   width: 100px !important;
   /* 表情包高度 */
   height: 100px !important;
   max-width: 100px !important;
   max-height: 100px !important;
   position: relative !important;
   transform: scale(1.0) !important;
   border-radius: 0 !important;
   border: none !important;
}
/* =============================================== */

/* 对方表情包位置 【不用改，上下偏移调top/left】 */
div[class*="message"] div[class*="bubble-them"]:not(:has([class*="avatar"])):not(:has(.msg-image-wrapper)):not(:has([class*="reply"])) img {
   top: 0px !important;
   left: 0px !important;
}

/* 我方表情包位置 【不用改】 */
div[class*="message"] div[class*="bubble-me"]:not(:has([class*="avatar"])):not(:has(.msg-image-wrapper)):not(:has([class*="reply"])) img {
   top: 0px !important;
   left: 0px !important;
}

/* 引用内缩略图（小预览图）尺寸，单独调整这里 */
[class*="reply"] img, 
[class*="quote"] img,
.msg-reply-block-media img {
   width: 50px !important;
   height: 50px !important;
   max-width: 50px !important;
   max-height: 50px !important;
   object-fit: cover !important;
   border-radius: 4px !important;
}

/* =========================================================
   🚫 万能去气泡补丁 (转账/礼物/图片/表情包 专属净化)
   ========================================================= */

/* ── 1. 扒掉外层气泡的背景、边框、阴影和内边距 ── */
.msg-bubble-container:has(.msg-transfer-card),
.msg-bubble-container:has(.gift-ig-container),
.msg-bubble-container:has(.msg-sim-card),
.msg-bubble-container:has(.msg-image-wrapper),
.msg-bubble-container:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block)),

.bubble-me-custom:has(.msg-transfer-card),
.bubble-me-custom:has(.gift-ig-container),
.bubble-me-custom:has(.msg-sim-card),
.bubble-me-custom:has(.msg-image-wrapper),
.bubble-me-custom:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block)),

.bubble-them-custom:has(.msg-transfer-card),
.bubble-them-custom:has(.gift-ig-container),
.bubble-them-custom:has(.msg-sim-card),
.bubble-them-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block)),

.msg-plain-me:has(.msg-transfer-card),
.msg-plain-me:has(.gift-ig-container),
.msg-plain-me:has(.msg-sim-card),
.msg-plain-me:has(.msg-image-wrapper),
.msg-plain-me:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block)),

.msg-plain-them:has(.msg-transfer-card),
.msg-plain-them:has(.gift-ig-container),
.msg-plain-them:has(.msg-sim-card),
.msg-plain-them:has(.msg-image-wrapper),
.msg-plain-them:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block)) {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    border-radius: 0 !important;
}

/* ── 2. 斩断气泡的小尾巴 (隐藏伪元素) ── */
.bubble-me-custom:has(.msg-transfer-card)::before,
.bubble-me-custom:has(.msg-transfer-card)::after,
.bubble-them-custom:has(.msg-transfer-card)::before,
.bubble-them-custom:has(.msg-transfer-card)::after,

.bubble-me-custom:has(.gift-ig-container)::before,
.bubble-me-custom:has(.gift-ig-container)::after,
.bubble-them-custom:has(.gift-ig-container)::before,
.bubble-them-custom:has(.gift-ig-container)::after,

.bubble-me-custom:has(.msg-sim-card)::before,
.bubble-me-custom:has(.msg-sim-card)::after,
.bubble-them-custom:has(.msg-sim-card)::before,
.bubble-them-custom:has(.msg-sim-card)::after,

.bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-me-custom:has(.msg-image-wrapper)::after,
.bubble-them-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(.msg-image-wrapper)::after,

.bubble-me-custom:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block))::before,
.bubble-me-custom:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block))::after,
.bubble-them-custom:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block))::before,
.bubble-them-custom:has(img):not(:has(.msg-text)):not(:has(.msg-reply-block))::after {
    display: none !important;
    content: none !important;
}

/* =========================================================
   📸 思维链终极美化：Instagram 帖子风格 (全 SVG 纯手工绘制)
   ========================================================= */

/* ── 1. 改造折叠按钮 (极简透明底，无三角) ── */
.chat-detail-screen {
  --thinking-btn-bg: transparent;
  --thinking-btn-color: #8e8e8e; /* Ins 经典的次级灰色 */
  --thinking-btn-border: none;
  --thinking-btn-shadow: none;
  --thinking-btn-padding: 4px 0px; 
}

/* ── 2. 隐藏默认图标、小三角，修改按钮文字 ── */
.nuo-thinking-icon { display: none !important; }
.nuo-thinking-arrow { display: none !important; } /* 🎯 咔嚓掉小三角 */
.nuo-thinking-label { font-size: 0 !important; }
.nuo-thinking-label::after {
    content: "@하트 비트" !important;
    font-size: 12px !important;
    font-weight: 600 !important;
    color: #8e8e8e !important;
}

/* ── 3. 改造面板基础样式 (Ins 经典白底卡片) ── */
.chat-detail-screen {
  --thinking-panel-bg: #ffffff;
  --thinking-panel-border-full: 1px solid #dbdbdb; /* Ins 标准边框色 */
  --thinking-panel-border-left: none; 
  --thinking-panel-radius: 4px;
  --thinking-panel-shadow: 0 1px 2px rgba(0,0,0,0.02); /* 极弱的阴影，几乎扁平 */

  /* 🎯 顶部留66px给Header，底部留90px给操作栏和点赞时间 */
  --thinking-panel-padding: 66px 16px 90px 16px;

  /* 正文文字样式 (Ins 帖子描述) */
  --thinking-text-color: #262626;
  --thinking-text-font-size: 14px;
  --thinking-text-font-style: normal;
  --thinking-text-line-height: 1.5;
  --thinking-panel-overflow: visible;
}

/* ── 4. 核心魔法：全 SVG 多重背景绘制 Ins 界面 ── */
.nuo-thinking-panel {
    background-image: 
        var(--char-avatar), /* 图层1: 顶部头像 */
        /* 图层2: 顶部右侧“更多”图标 (三个点) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23262626' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='1.5'/><circle cx='19' cy='12' r='1.5'/><circle cx='5' cy='12' r='1.5'/></svg>"),
        /* 图层3: 顶部横向分割线 */
        linear-gradient(to right, #efefef, #efefef),
        /* 图层4: 底部左侧操作栏 (爱心、评论、纸飞机) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='100' height='24' viewBox='0 0 100 24'><style>.icon{fill:none;stroke:%23262626;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;}</style><path class='icon' d='M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z' transform='translate(0,0)'/><path class='icon' d='M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z' transform='translate(38,0)'/><g transform='translate(76,0)'><line class='icon' x1='22' y1='2' x2='11' y2='13'/><polygon class='icon' points='22 2 15 22 11 13 2 9 22 2'/></g></svg>"),
        /* 图层5: 底部右侧“收藏”图标 */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23262626' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z'/></svg>"),
        /* 图层6: 底部文字 (点赞数 + 时间) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='40' viewBox='0 0 200 40'><style>.likes{font-family:system-ui,-apple-system,sans-serif;font-size:13px;font-weight:600;fill:%23262626;}.time{font-family:system-ui,-apple-system,sans-serif;font-size:11px;fill:%238e8e8e;}</style><text x='0' y='14' class='likes'>10,245 次赞</text><text x='0' y='34' class='time'>2 小时前</text></svg>") !important; 

    /* 📐 控制各个图层的大小 */
    background-size: 
        32px 32px, /* 图层1: 头像大小 */
        20px 20px, /* 图层2: 更多图标大小 */
        100% 1px,  /* 图层3: 分割线贯穿全宽 */
        100px 24px, /* 图层4: 左侧操作栏大小 */
        24px 24px, /* 图层5: 收藏图标大小 */
        200px 40px !important; /* 图层6: 底部文字大小 */

    /* 📍 控制各个图层的位置 */
    background-position: 
        16px 12px, /* 图层1: 头像 (左上角) */
        calc(100% - 16px) 18px, /* 图层2: 更多图标 (右上角) */
        0 56px, /* 图层3: 分割线 (头像下方) */
        16px calc(100% - 54px), /* 图层4: 操作栏 (距底54px) */
        calc(100% - 16px) calc(100% - 54px), /* 图层5: 收藏 (距底54px，靠右) */
        16px calc(100% - 8px) !important; /* 图层6: 文字 (最底部) */

    background-repeat: no-repeat !important;
}

/* ── 5. 强制头像变成正圆 (Ins风格) ── */
.nuo-thinking-panel {
    /* 利用伪元素遮罩或者直接在背景图上无法改圆角，但我们可以用一个巧妙的技巧 */
    /* 实际上 var(--char-avatar) 只是图片，圆角由系统控制，这里我们不强求，通常已经是圆的了 */
}

/* ── 6. 绘制顶部 Header 的名字 ── */
.nuo-thinking-panel::before {
    content: var(--char-name) !important;
    position: absolute !important;
    top: 18px !important;
    left: 58px !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    color: #262626 !important;
    z-index: 2 !important;
    display: block !important;
}

/* ── 7. 清空原本的 after ── */
.nuo-thinking-panel::after {
    display: none !important;
}

/* =========================================================
   ⏱️ 聊天界面时间戳美化：灰色胶囊风格
   ========================================================= */

/* ── 1. 消息之间的时间戳 (如：下午 2:30) ── */
.timestamp-custom {
    background-color: rgba(0, 0, 0, 0.06) !important; /* 极浅的灰色背景 */
    color: #8e8e8e !important; /* 经典的次级灰文字 */
    padding: 4px 12px !important; /* 撑开胶囊的内边距 */
    border-radius: 100px !important; /* 完美的胶囊圆角 */
    font-size: 11px !important;
    font-weight: 500 !important;
    width: fit-content !important; /* 宽度紧贴文字 */
    margin: 16px auto 12px auto !important; /* 保证绝对居中，上下留白 */
    backdrop-filter: blur(4px) !important; /* 微微的毛玻璃质感 */
}

/* ── 2. 日期分隔线 (如：今天、昨天) 保持同款胶囊风格 ── */
:root {
    --date-divider-bg: rgba(0, 0, 0, 0.06);
    --date-divider-color: #8e8e8e;
    --date-divider-size: 11px;
    --date-divider-weight: 500;
    --date-divider-padding: 4px 12px;
    --date-divider-radius: 100px;
    --date-divider-margin: 16px 0;
}

/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ =========================================================
   💬 深黑顶栏 · 微信绿气泡 · 锐利高光质感版
   ========================================================= */
:root {
  /* === 全局背景 === */
  --chat-bg-color: #ffffff;

  /* 顶栏基础变量 */
  --chat-header-height: 56px;

  /* 🎯🎯 主标题(备注)设置 🎯🎯 */
  --chat-header-title-color: #333333; /* 配合银灰，字色用纯正深灰 */
  --chat-header-title-size: 17px;
  --chat-header-title-weight: 600;
  --title-top-position: 70%; 

  /* 🎯🎯 自定义副标题设置 🎯🎯 */
  --custom-subtitle-text: "在线"; 
  --custom-subtitle-color: #888888; /* 中灰 */
  --custom-subtitle-size: 11px;
  --custom-subtitle-top: 22px; 

  /* 隐藏系统原生副标题和头像 */
  --chat-header-subtitle-color: transparent;
  --chat-header-subtitle-size: 0px;
  --chat-header-avatar-size: 0px;

  /* === 素净模式布局 === */
  --plain-gap-between-groups: 20px;
  --plain-gap-within-group: 6px;
  --plain-content-max-width: 65%;
  --plain-padding-left-me: 60px;
  --plain-padding-right-me: 0px;
  --plain-padding-left-them: 0px;
  --plain-padding-right-them: 60px;
  --plain-avatar-size: 42px;
  --plain-avatar-radius: 6px;
  --plain-avatar-gap: 10px;

/* =========================================================
   🎯🎯 顶栏定制 (极浅银灰 + 锐利高光) 🎯🎯
   ========================================================= */
.chat-header-custom {
  /* 🎯 极浅的冷灰色渐变 */
  background: linear-gradient(to bottom, #ffffff 0%, #f0f0f0 100%) !important;
  border-bottom: 1px solid #d4d4d4 !important;
  /* 🎯 纯白色锐利高光，质感拉满 */
  box-shadow: inset 0 1px 0 #ffffff !important; 
  position: relative !important;
}

.chat-header-custom .chat-header-title {
  text-shadow: 0 1px 0 #ffffff !important; /* 纯白下阴影，雕刻感更强 */
  position: absolute !important;
  left: 50% !important;
  top: var(--title-top-position) !important; 
  transform: translate(-50%, -50%) !important;
  margin: 0 !important;
  padding: 0 !important;
  width: max-content !important;
  z-index: 10 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  overflow: visible !important;
}

.header-avatar-container { display: none !important; }
.chat-header-subtitle { display: none !important; } 

.chat-header-custom .chat-header-title::after {
  content: var(--custom-subtitle-text) !important;
  position: absolute !important;
  top: var(--custom-subtitle-top) !important; 
  left: 50% !important;
  transform: translateX(-50%) !important;
  color: var(--custom-subtitle-color) !important;
  font-size: var(--custom-subtitle-size) !important;
  font-weight: 400 !important;
  white-space: nowrap !important;
}

.header-btn-phone, .header-btn-video { 
  opacity: 0 !important; 
  pointer-events: auto !important; 
}

.header-btn-back svg { display: none !important; }
.header-btn-back::after {
  content: "" !important;
  position: absolute !important;
  left: 16px !important;
  width: 24px !important; 
  height: 24px !important;
  /* 图标换成深灰 */
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23333333' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><polyline points='15 18 9 12 15 6'/></svg>") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.header-btn-info svg { display: none !important; }
.header-btn-info {
  position: relative !important;
  width: 32px !important;
  height: 32px !important;
}
.header-btn-info::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  /* 图标换成深灰 */
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23333333'><circle cx='5' cy='12' r='2'/><circle cx='12' cy='12' r='2'/><circle cx='19' cy='12' r='2'/></svg>") !important;
  background-size: 24px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* ===== 仿微信底栏 (极浅银灰立体质感版 + 顶部间距优化) ===== */
:root {
    /* 基础变量保留，但实际质感由下面的 class 覆盖 */
    --input-area-blur: 0px;
